// Interface translations. One picker drives both the UI language and the AI
// output language (aiLangFor). Focus languages: English / Spanish / French.
// Brand name, SRS jargon shown as data (reps/ease), citation markers [n] and URL
// examples are intentionally not translated.
import { state } from './state.js';

export const interfaceLangs = [['en', 'English'], ['es', 'Español'], ['fr', 'Français']];
export const SUPPORTED_LANGS = interfaceLangs.map(([code]) => code);

// Interface language code → language name used in AI prompts.
const AI_LANG = { en: 'English', es: 'Spanish', fr: 'French' };
export function aiLangFor(code) { return AI_LANG[code] || 'English'; }

